// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure the caller is not the current owner, to test the property
        vm.assume(caller != c.owner());
        vm.assume(newOwner != c.owner());
        // Attempt transferOwnership from the non-owner caller
        vm.prank(caller);
        // The reference should revert, buggy should succeed; assert that owner is unchanged
        try c.transferOwnership(newOwner) {
            // If the call succeeds, owner must remain the original owner (bug case would change it)
            assertTrue(c.owner() == c.owner());
        } catch {
            // If the call reverts, owner must remain unchanged (this is the expected reference behavior)
            assertTrue(c.owner() == c.owner());
        }
    }
}

