pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // Ensure the initial owner is a well-defined non-zero address distinct from caller and newOwner
        address initialOwner = c.owner();
        vm.assume(initialOwner != address(0));
        vm.assume(caller != initialOwner);
        vm.assume(newOwner != initialOwner);

        bool success;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // The reference contract must revert when a non-owner calls transferOwnership.
        // Since we assumed caller is not the owner, the call must revert.
        // The bug version ignores the modifier, so the call succeeds and updates owner.
        assertTrue(!success);
    }
}

