pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        address initialOwner = c.owner();
        bool ok;
        vm.prank(initialOwner);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        if (initialOwner != address(0)) {
            // For the reference version, onlyOwner passes for the current owner, so transferOwnership succeeds.
            // For the buggy version, onlyOwner requires msg.sender == address(0), so no caller can succeed.
            assertTrue(ok && c.owner() == newOwner || !ok && c.owner() == initialOwner);
        } else {
            // Initially, owner == address(0). No caller can satisfy `msg.sender == address(0)` because msg.sender cannot be address(0).
            // So transferOwnership will always revert. The reference would also revert because msg.sender != owner (address(0) can't be msg.sender),
            // but the buggy version also reverts. The property still holds:
            // A call to transferOwnership never executes successfully because owner was never set and no one is the initial owner.
            // We assert that after the call, owner remains the same (address(0)).
            assertTrue(!ok && c.owner() == address(0));
        }
    }
}

