pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set an initial owner so the reference can satisfy onlyOwner.
        // The owner is set by the test deployer (address(this)).
        c.transferOwnership(address(this));
    }

    function testFuzz_property(address caller, address newOwner) public {
        // Exclude precompile/zero addresses that may cause special behavior, keep domain wide.
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // Attempt transferOwnership as the fuzzed caller
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));

        // On reference: if caller is the owner (address(this)), ok == true;
        // otherwise, ok == false (onlyOwner fails).
        // On mutant: onlyOwner requires msg.sender == address(0), so ok == false always.
        // The universal property: the success of transferOwnership is equivalent to whether caller is the current owner.
        // This holds for reference and fails for mutant when caller == owner (here address(this)).
        bool isOwner = (caller == c.owner());
        assertTrue(ok == isOwner);
    }
}

